SELECT COUNT(*) AS N_ROWS
     , SUM(CASE WHEN RDXSRC_CODE IS NULL OR TRIM(CAST(RDXSRC_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRC_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSRC_CODE
     , SUM(CASE WHEN REP_CODE IS NULL OR TRIM(CAST(REP_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(REP_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_REP_CODE
     , SUM(CASE WHEN CMS_COLL_ID IS NULL OR TRIM(CAST(CMS_COLL_ID AS STRING)) = '' OR LOWER(TRIM(CAST(CMS_COLL_ID AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_CMS_COLL_ID
     , SUM(CASE WHEN RDXSRC_COLL_ITEM_ID IS NULL OR TRIM(CAST(RDXSRC_COLL_ITEM_ID AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRC_COLL_ITEM_ID AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_ITEM_ID
     , SUM(CASE WHEN CREATE_DATE IS NULL OR TRIM(CAST(CREATE_DATE AS STRING)) = '' OR LOWER(TRIM(CAST(CREATE_DATE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_CREATE_DATE
     , SUM(CASE WHEN SPC_SURPRISE_CHECK IS NULL OR TRIM(CAST(SPC_SURPRISE_CHECK AS STRING)) = '' OR LOWER(TRIM(CAST(SPC_SURPRISE_CHECK AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_SURPRISE_CHECK
FROM `${hivevar:tmp_db}`.`${hivevar:prefix}STOCK_ITEM`;
